{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Vendor SLA Data",
    "url": "http://localhost:7804",
    "widgets_json": {
      "latency_history": {
        "name": "Latency History",
        "description": "Vendor latency history.",
        "endpoint": "/latency-history",
        "type": "table",
        "gridData": {
          "w": 20,
          "h": 9
        },
        "staleTime": 900000,
        "data": {
          "columnsDefs": [
            {
              "field": "day",
              "headerName": "Day",
              "cellDataType": "dateString",
              "formatterFn": "dateString"
            },
            {
              "field": "latency_ms",
              "headerName": "Latency Ms",
              "cellDataType": "number"
            },
            {
              "field": "vendor",
              "headerName": "Vendor",
              "cellDataType": "text"
            },
            {
              "field": "breach",
              "headerName": "Breach",
              "cellDataType": "boolean"
            }
          ]
        }
      },
      "breach_metric": {
        "name": "Open Breaches",
        "description": "Count of open SLA breaches.",
        "endpoint": "/breach-count",
        "type": "metric",
        "w": 6,
        "h": 4
      }
    },
    "apps_json": [
      {
        "name": "Vendor Health",
        "description": "Latency and breach posture.",
        "tabs": {
          "latency": {
            "id": "latency",
            "name": "Latency",
            "layout": [
              {
                "i": "latency_history",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          },
          "signals": {
            "id": "signals",
            "name": "Signals",
            "layout": [
              {
                "i": "breach_metric",
                "x": 0,
                "y": 0,
                "w": 12,
                "h": 6
              }
            ]
          }
        }
      }
    ]
  }
}
